WITH orders_by_store AS (SELECT store_id, ROUND(STDDEV(amount), 2) AS stddev_amount, COUNT(CASE WHEN status = 'SHIPPED' THEN 1 END) AS shipped_count FROM orders GROUP BY store_id) SELECT stores.region, stores.store_name, orders_by_store.stddev_amount, orders_by_store.shipped_count FROM stores LEFT JOIN orders_by_store ON stores.id = orders_by_store.store_id WHERE orders_by_store.stddev_amount >= 25 ORDER BY stores.region DESC
